from main import countdown


def test_counts_down():
    assert countdown(3) == [3, 2, 1]


def test_one():
    assert countdown(1) == [1]


def test_zero_is_empty():
    assert countdown(0) == []


def test_larger():
    assert countdown(100)[0] == 100
    assert countdown(100)[-1] == 1
    assert len(countdown(100)) == 100
